// 這顆只用來看 Webhook 出來的 item 長什麼樣子
const items = $input.all();

// ★ print 加在這一行「下面」：列出每個 item 的 json / binary 鍵
console.log('[檢查binary結構] 收到 items 數量:', items.length);
items.forEach((item, idx) => {
  console.log(`[檢查binary結構] item #${idx} keys:`, Object.keys(item));
  console.log(`[檢查binary結構] item #${idx} has binary:`, !!item.binary);
  if (item.binary) {
    console.log(`[檢查binary結構] item #${idx} binary keys:`, Object.keys(item.binary));
  }
});

// ★ 這裡不動，原樣把所有東西傳給下一顆（包含 binary）
return items;

// ====================================================================
// 準備API請求：將 binary.file 轉換為 base64 供 Flask API 使用
// ====================================================================

const items = $input.all();

if (!items.length) {
  throw new Error('[準備API] 沒有收到任何 item，請確認前置節點');
}

// 取得第一個 item
const item = items[0];

// ★ print 加在這一行「下面」：先看整個 item 結構
console.log('[準備API][DEBUG] item 結構:', {
  keys: Object.keys(item),
  hasBinary: !!item.binary,
  hasJson: !!item.json,
});

const binary = item.binary || {};
const json = item.json || {};

// ★ print 加在這一段「下面」：看 binary 裡有哪些欄位
console.log('[準備API][DEBUG] binary keys:', Object.keys(binary));

// 嘗試從 binary.file 或 binary.data 取得檔案；若都沒有，就抓第一個 key
let binSource = null;

if (binary.file) {
  binSource = binary.file;
  console.log('[準備API] 來源: binary.file');
} else if (binary.data) {
  binSource = binary.data;
  console.log('[準備API] 來源: binary.data');
} else {
  const keys = Object.keys(binary);
  if (keys.length > 0) {
    const firstKey = keys[0];
    binSource = binary[firstKey];
    console.log(`[準備API] 來源: binary.${firstKey} (自動偵測)`);
  } else {
    console.log('[準備API][ERROR] binary 為空物件:', binary);
    throw new Error('[準備API] 找不到可用的 binary 檔案 (file/data)');
  }
}

// 取得 base64 資料
const base64Data = binSource.data;

if (!base64Data) {
  // ★ print 加在這裡「下面」：base64Data 沒東西時，把 binSource 印出來
  console.log('[準備API][ERROR] binSource 內容為:', binSource);
  throw new Error('[準備API] binary 中沒有 data 欄位');
}

// ★ print 加在這裡「下面」：截一小段 base64 看格式
console.log('[準備API] base64 長度:', base64Data.length);
console.log('[準備API][DEBUG] base64 前 80 字:', String(base64Data).slice(0, 80));

// 嘗試取得客戶名稱（從查詢參數或 JSON）
const clientName = 
  json.client_name ||
  (json.query && json.query.client_name) ||
  '未指定客戶';

console.log('[準備API] 客戶名稱:', clientName);
console.log('[準備API] ✅ 準備完成');

// 回傳給下一個節點
return [{
  json: {
    file_base64: base64Data,
    client_name: clientName
  }
}];

// ====================================================================
// 轉換Base64為Binary：將 Flask 回傳的 base64 轉為 n8n binary 格式
// ====================================================================

const res = $input.first().json;

console.log('[轉換Binary] 收到 Flask 回應:', {
  success: res.success,
  file_name: res.file_name,
  has_base64: !!res.file_base64,
  report: res.report
});

if (!res.success) {
  throw new Error('Security C API 處理失敗: ' + (res.error || '未知錯誤'));
}

const fileBase64 = res.file_base64;
const fileName = res.file_name || 'security_c_result.xlsx';
const report = res.report || {};

if (!fileBase64) {
  throw new Error('Flask 回應中沒有 file_base64');
}

console.log('[轉換Binary] 檔案名稱:', fileName);
console.log('[轉換Binary] base64 長度:', fileBase64.length);
console.log('[轉換Binary] 比對報告:', report);

// 轉換為 binary 格式
return [{
  json: {
    success: true,
    file_name: fileName,
    report: report
  },
  binary: {
    data: {
      data: fileBase64,
      fileName: fileName,
      mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    }
  }
}];
